import{_ as o,o as t,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Keynote: Lead Developers Town Hall","description":"","frontmatter":{"title":"Keynote: Lead Developers Town Hall","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","升级","认证","性能优化","文档改进"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Keynote_-_Lead_Developers_Town_Hall.md","filePath":"posts/2023/Keynote_-_Lead_Developers_Town_Hall.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Keynote_-_Lead_Developers_Town_Hall.md"};function r(a,e,i,p,_,c){return t(),l("div",null,[...e[0]||(e[0]=[s("<p>在“Keynote: Lead Developers Town Hall”会议中，Ceph社区的开发者们讨论了一系列关键议题，包括升级问题、认证、性能优化以及文档改进。</p><p><strong>主要议题及讨论内容</strong>：</p><ul><li><strong>升级问题</strong>：社区探讨了从Octopus直接升级到Reef是否可行，得出结论为不可行，因为Ceph支持一次升级两个版本，只能从Octopus直接升级到Pacific或Quincy。</li><li><strong>认证问题</strong>：讨论了在不停机的情况下如何添加认证，并建议联系Zach获取更多细节。</li><li><strong>PG资源消耗</strong>：目前没有直接方法获取PG的CPU或内存消耗，但可以通过收集和聚合相关指标来推断。</li><li><strong>冻结数据迁移</strong>：讨论了将冻结数据迁移到磁带存储的计划，Crimson项目可能是未来的解决方案。</li><li><strong>性能改进</strong>：正在测试新均衡器对读取IOPS和吞吐量的性能改进，具体数据尚未公布。</li><li><strong>大桶删除</strong>：讨论了如何快速删除包含数百万文件的大桶，同时不overload集群，可以通过增加垃圾回收队列和调整相关设置来实现。</li><li><strong>SSD性能优化</strong>：讨论了如何配置OSD以最大化NVMe设备的性能，需要根据具体工作负载进行调整。</li><li><strong>文档改进</strong>：鼓励社区成员通过访问docs.ceph.com参与文档的改进工作，特别是编写初学者指南和概述段落。</li></ul><p><strong>决定事项</strong>：</p><ul><li>确认可以通过文档添加认证，建议联系Zach获取更多细节。</li><li>社区将致力于改进文档，特别是编写初学者指南和概述段落。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Zach将负责更新认证相关的文档，确保包含不停机的具体步骤。</li><li>继续进行新均衡器的性能测试，并及时公布测试结果。</li><li>鼓励社区成员通过docs.ceph.com参与文档的改进工作。</li></ul><p><strong>其他讨论</strong>：</p><ul><li>讨论了Ceph Gateway的多站点配置和重启桶的当前支持情况。</li><li>强调了IPv6支持的重要性，并讨论了可能的解决方案。</li></ul><p>此次会议为Ceph社区的开发者们提供了一个交流和合作的机会，共同推动Ceph的发展。</p>",10)])])}const u=o(n,[["render",r]]);export{g as __pageData,u as default};
